package com.lmspilot.identity.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.*; @Entity @Table(name="roles") public class RoleEntity { @Id public UUID id=UUID.randomUUID(); @Column(nullable=false,unique=true,length=80) public String code=""; @Column(nullable=false,length=160) public String name=""; @ElementCollection(fetch=FetchType.EAGER) @CollectionTable(name="role_permissions",joinColumns=@JoinColumn(name="role_id")) @Column(name="permission",nullable=false,length=120) public Set<String> permissions=new LinkedHashSet<>(); @Column(nullable=false) public boolean systemRole; @Column(nullable=false) public Instant createdAt=Instant.now(); @Column(nullable=false) public Instant updatedAt=Instant.now(); @Version public long version; public RoleEntity(){} }
